def keep_existing_sharing(apps, schema_editor):
    """Under the new rule a record is shared only after acceptance and an explicit send. Referrals that were already
    accepted with consent stay shared; completed ones are locked."""
    R = apps.get_model('hospital', 'Referral')
    for r in R.objects.filter(consent_to_share=True, status__in=['accepted', 'transferred'], shared_at__isnull=True):
        R.objects.filter(pk=r.pk).update(shared_at=r.sent_at or r.updated_at)
    for r in R.objects.filter(status__in=['completed', 'declined', 'cancelled'], locked_at__isnull=True):
        R.objects.filter(pk=r.pk).update(locked_at=r.completed_at or r.updated_at)


